let worldUI = { selected: 'guam', region: '전체', zoom: 1 };
const worldPoint = d => [(d.lon + 180) * 1000 / 360, (84 - d.lat) * 440 / 144];
function worldMarkup() {
  const regions = ['전체', '아시아', '유럽', '북미', '남미', '아프리카', '오세아니아'];
  return `<section class="card" aria-label="세계 여행지 탐색">
    <div class="world-heading"><div><h2>지도로 떠나는 세계여행</h2><p class="muted small">대표 여행지 12곳 · 지도나 이름에 마우스를 올려보세요. 휴대폰에서는 터치하세요.</p></div>
    <label class="small">지역 선택<select class="world-filter" id="world-region">${regions.map(r => `<option ${r === worldUI.region ? 'selected' : ''}>${r}</option>`).join('')}</select></label></div>
    <div class="world-layout"><div class="world-main"><div class="world-map">
      <div class="world-controls"><button type="button" class="ghost" id="world-out" aria-label="지도 축소">− 축소</button><button type="button" class="ghost" id="world-in" aria-label="선택 여행지 중심 확대">＋ 확대</button><button type="button" class="ghost" id="world-reset">세계 전체</button></div>
      <svg id="world-svg" viewBox="0 0 1000 440" role="group" aria-label="세계 지도. 여행지 표시는 키보드 Tab과 Enter로도 선택할 수 있습니다.">
        <path class="world-grid" d="${[0,30,60,-30,-60].map(lat => `M0 ${(84-lat)*440/144}H1000`).join(' ')} ${[-120,-60,0,60,120].map(lon=>`M${(lon+180)*1000/360} 0V440`).join(' ')}"/>
        <path class="world-land" d="${WORLD_LAND}"/>
        ${WORLD_DESTS.map(d => {const [x,y]=worldPoint(d);return `<g class="world-pin" data-world-pin="${d.id}" role="button" tabindex="0" aria-label="${esc(d.city)} 여행 정보" aria-pressed="false" transform="translate(${x},${y})"><circle class="halo" r="9"/><circle class="dot" r="5"/><title>${esc(d.city)} · ${esc(d.country)}</title>${d.label ? `<text x="${d.dx || 10}" y="${d.dy || -10}" text-anchor="${d.dx < 0 ? 'end' : 'start'}">${esc(d.city)}</text>` : ''}</g>`;}).join('')}
      </svg></div><div class="world-places" id="world-places" aria-label="여행지 목록">${WORLD_DESTS.map(d => `<button type="button" class="ghost" data-world-city="${d.id}" aria-pressed="false">${esc(d.city)}</button>`).join('')}</div>
      <p class="world-footnote" style="margin-top:10px">지도: <a href="https://www.naturalearthdata.com/about/terms-of-use/" target="_blank" rel="noopener noreferrer">Natural Earth · 공개 데이터</a>. 위치는 대표 지점 기준이며, 작은 섬은 지도 윤곽에서 생략될 수 있어요.</p>
    </div><aside class="world-detail" id="world-detail" aria-label="선택한 여행지 상세 정보"></aside></div>
    <div id="world-msg" role="status"></div>
    <p class="world-footnote">관광·먹거리 참고 정보 · 여행경보를 실시간 조회하는 지도는 아니에요. 출발 전 <a href="https://www.0404.go.kr/" target="_blank" rel="noopener noreferrer">외교부 해외안전여행</a>과 관광지 공식 안내를 확인하세요.</p>
  </section>`;
}
function bindWorld() {
  const root = P(), detail = $('#world-detail'), svg = $('#world-svg');
  if (!detail || !svg) return;
  const visible = d => worldUI.region === '전체' || d.region === worldUI.region;
  const registered = d => state.candidates.some(c => vkey(c.city,c.country) === vkey(d.city,d.country));
  const updateView = () => {
    const d = WORLD_DESTS.find(d => d.id === worldUI.selected), [cx,cy]=worldPoint(d);
    const w=1000/worldUI.zoom, h=440/worldUI.zoom;
    const x=Math.max(0,Math.min(1000-w,cx-w/2)), y=Math.max(0,Math.min(440-h,cy-h/2));
    svg.setAttribute('viewBox', `${x} ${y} ${w} ${h}`);
    $('#world-out').disabled=worldUI.zoom===1; $('#world-in').disabled=worldUI.zoom===4;
  };
  const select = id => {
    const d = WORLD_DESTS.find(d=>d.id===id); if (!d) return;
    worldUI.selected=id;
    root.querySelectorAll('[data-world-pin], [data-world-city]').forEach(el=>el.setAttribute('aria-pressed',String((el.dataset.worldPin || el.dataset.worldCity)===id)));
    const blocked=Core.isExcluded(d.country,state.excluded), added=registered(d);
    const ph=d.asset ? WORLD_PHOTOS[d.asset] : null;
    const image=ph?.image || DEST_IMG[d.img];
    detail.innerHTML=`<img src="${image}" alt="${esc(d.city)} 풍경" width="480" height="300"><div class="world-detail-body">
      <div><span class="tag">${esc(d.region)} · ${esc(d.country)}</span><h3>${esc(d.city)}</h3></div>
      <p class="small muted">${esc(d.desc)}</p>
      <div><b>가볼 만한 곳</b><ul>${d.sights.map(x=>`<li>${esc(x)}</li>`).join('')}</ul></div>
      <div><b>맛보고 싶은 먹거리</b><p class="small">${esc(d.food)}</p></div>
      <div class="world-actions"><button type="button" data-world-add="${d.id}" ${blocked || added || spinning ? 'disabled' : ''}>${blocked ? '룰렛 제외 국가' : added ? '✓ 후보 등록됨' : '＋ 여행 후보 추가'}</button>
      <a class="small" href="https://www.google.com/maps/search/?api=1&query=${d.lat},${d.lon}" target="_blank" rel="noopener noreferrer">지도에서 보기 ↗</a></div>
      <div class="small">${d.sources.map((u,i)=>`<a href="${esc(u)}" target="_blank" rel="noopener noreferrer">${i===0?'공식 관광 안내':'먹거리 안내'} ↗</a>`).join(' · ')}</div>
      <p class="world-credit">${ph ? `사진: ${esc(ph.author)} · <a href="${esc(ph.credit)}" target="_blank" rel="noopener noreferrer">원본</a> · <a href="${ph.licenseUrl}" target="_blank" rel="noopener noreferrer">${esc(ph.license)}</a> · 크기·압축 조정 / 화면에 맞춰 자름` : '기존 사이트에 포함된 여행지 시안 이미지'}</p>
    </div>`;
    detail.querySelector('[data-world-add]').onclick=()=>{
      if(spinning) return showMsg($('#world-msg'),'룰렛이 멈춘 뒤 후보를 추가해 주세요.','info');
      if(blocked || registered(d)) return;
      state.candidates.push({city:d.city,country:d.country});
      if(!save()){return showMsg($('#world-msg'),'저장 공간이 부족하거나 저장이 제한되어 후보를 추가하지 못했어요.','bad');}
      if(tab==='roulette')roulette();else select(id);
      showMsg($('#world-msg'),`${d.city}를 후보에 추가했어요. 추천·투표와 룰렛에서 확인하세요.`,'good');
    };
    updateView();
  };
  const filter = () => {
    root.querySelectorAll('[data-world-pin], [data-world-city]').forEach(el=>{
      const d=WORLD_DESTS.find(d=>d.id===(el.dataset.worldPin || el.dataset.worldCity));
      el.style.display=visible(d)?'':'none';
    });
    if(!visible(WORLD_DESTS.find(d=>d.id===worldUI.selected)))worldUI.selected=WORLD_DESTS.find(visible).id;
    select(worldUI.selected);
  };
  root.querySelectorAll('[data-world-pin], [data-world-city]').forEach(el=>{
    const id=el.dataset.worldPin || el.dataset.worldCity;
    el.addEventListener('mouseenter',()=>{if(worldUI.selected!==id)select(id);});
    el.addEventListener('focus',()=>{if(worldUI.selected!==id)select(id);});
    el.addEventListener('click',()=>select(id));
    if(el.dataset.worldPin)el.addEventListener('keydown',e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();select(id);}});
  });
  $('#world-region').onchange=e=>{worldUI.region=e.target.value;worldUI.zoom=1;filter();};
  $('#world-in').onclick=()=>{worldUI.zoom=Math.min(4,worldUI.zoom*2);updateView();};
  $('#world-out').onclick=()=>{worldUI.zoom=Math.max(1,worldUI.zoom/2);updateView();};
  $('#world-reset').onclick=()=>{worldUI.zoom=1;worldUI.region='전체';$('#world-region').value='전체';filter();};
  filter();
}


/* ---------- 상태 ---------- */
let state = load();
if (state) { state.votes ||= {}; state.links ||= DEFAULT_LINKS.map(l => ({ ...l })); }
let me = null; // 로그인한 사용자 (메모리에만)
let tab = "overview";
let onlyAgreed = false;

function hydrateStoredState(original) {
  const clean=Core.normalizeState(original);
  for(const k of ['salt','codeHash','adminSalt','adminHash'])if(typeof original[k]==='string'&&original[k].length<=256)clean[k]=original[k];
  clean.fails=Number.isInteger(original.fails)?Math.max(0,Math.min(5,original.fails)):0;
  clean.lockUntil=Number.isFinite(original.lockUntil)&&original.lockUntil>0?original.lockUntil:0;
  return clean;
}
function load() {
  try {
    const raw = localStorage.getItem(activeKey); if (!raw) return null;
    const original = JSON.parse(raw);
    const clean = hydrateStoredState(original);
    snapshots.set(activeKey, raw); return clean;
  } catch {
    $('#storage-status').hidden = false;
    $('#storage-status').textContent = '여행 데이터를 읽지 못했어요. 손상된 데이터는 덮어쓰지 않습니다. 백업이 있다면 새 여행으로 복원해 주세요.';
    return null;
  }
}
function save() {
  if (demoMode) return true;
  try {
    if (revisionConflict) throw new Error('다른 탭에서 여행이 바뀌었어요. 시작 화면에서 여행을 다시 열어 주세요.');
    const previous = snapshots.get(activeKey);
    if (previous !== undefined && localStorage.getItem(activeKey) !== previous) {
      revisionConflict = true; throw new Error('다른 탭에서 여행이 바뀌었어요. 시작 화면에서 여행을 다시 열어 주세요.');
    }
    const clean=hydrateStoredState(state);
    const data = JSON.stringify(clean); localStorage.setItem(activeKey, data); snapshots.set(activeKey, data); state=clean;
    $('#storage-status').hidden = true; return true;
  } catch (error) {
    const raw = snapshots.get(activeKey);
    if (raw) state = hydrateStoredState(JSON.parse(raw));
    $('#storage-status').hidden = false;
    $('#storage-status').textContent = revisionConflict ? error.message : '저장하지 못했어요. 변경을 취소했으니 저장 공간이나 브라우저 설정을 확인해 주세요.';
    return false;
  }
}
function commit(mutator) {
  const before = JSON.stringify(state);
  try { mutator(state); } catch (error) { state = JSON.parse(before); toast(error.message); return false; }
  if (save()) return true;
  state = JSON.parse(before); return false;
}

function exampleData(trip) {
  const d = trip.start || "2026-12-24";
  const next = (n) => { const t = new Date(d + "T00:00:00"); t.setDate(t.getDate() + n); return localDate(t); };
  const m = trip.members.map(x => x.name);
  const pick = i => m[i % m.length];
  return {
    schedule: [
      { id: uid(), date: d, time: "09:30", place: "김포공항 출발", note: "예시 일정 · 2시간 전 도착" },
      { id: uid(), date: d, time: "12:30", place: "제주 동문시장 점심", note: "" },
      { id: uid(), date: d, time: "15:00", place: "숙소 체크인", note: "예약번호는 앞 4자리만 적기" },
      { id: uid(), date: next(1), time: "10:00", place: "성산일출봉", note: "" },
      { id: uid(), date: next(1), time: "14:00", place: "우도", note: "배편 시간 확인" },
    ],
    packing: [
      { id: uid(), item: "여행자 보험 확인", owner: pick(0), done: true },
      { id: uid(), item: "상비약", owner: pick(1), done: false },
      { id: uid(), item: "보조배터리 2개", owner: pick(2), done: false },
      { id: uid(), item: "우산", owner: pick(3), done: false },
    ],
    expenses: [
      { id: uid(), item: "항공권(예시)", amount: 320000, payer: pick(0) },
      { id: uid(), item: "렌터카(예시)", amount: 140000, payer: pick(1) },
      { id: uid(), item: "점심(예시)", amount: 52000, payer: pick(2) },
    ],
    posts: [{ id: uid(), author: pick(0), text: "예시 글: 출발 전날 짐 싸기 완료!", img: "", time: Date.now() }],
  };
}

/* ---------- 화면 전환 ---------- */
function setHero(titleHtml, sub, facts) {
  $("#h-trip").innerHTML = titleHtml;
  $("#h-sub").textContent = sub;
  $("#h-facts").innerHTML = (facts || []).map(([k, v]) => `<span class="fact">${esc(k)} <b>${esc(v)}</b></span>`).join("");
}
function show(view) {
  document.body.dataset.view=view;
  if(view!=='app'){cancelRoulette();clearToast();}if(view!=='gate')clearInterval(lockTimer);
  ['welcome','trips','setup','gate','app'].forEach(v=>$('#v-'+v).hidden=v!==view);
  const content=view==='app'?$('#panel'):$('#v-'+view);content.tabIndex=-1;$('.skip-link').setAttribute('href','#'+content.id);
  $('#who').hidden=view!=='app';$('#home-entry').hidden=view==='welcome';
  $('#reset-wrap').hidden=!(view==='app'&&me?.admin&&!demoMode);
  $('#demo-notice').hidden=!(view==='app'&&demoMode);$('#logout').textContent=demoMode?'체험 종료':'나가기';
  if(view==='welcome'){setHero('우리 가족,<br>이번엔 <em>어디</em>로 떠날까요?','새 여행은 직접 만들고, 예시는 코드 없이 둘러보세요.',[]);renderWelcome();}
  if(view==='trips'){setHero('우리 가족 여행을<br><em>이어서</em> 준비해요','이 브라우저에 저장된 여행을 선택하세요.',[]);renderSavedTrips();}
  if(view==='setup')setHero('우리 가족만의<br><em>새 여행</em> 만들기','관리자 이름과 시크릿코드는 지금 직접 정합니다.',[['기존 여행','그대로 보관'],['새 여행','빈 일정으로 시작']]);
  if(view==='gate'){setHero('함께 준비하는<br><em>우리 가족</em> 여행',state.trip.name+' · 등록한 이름과 코드로 입장하세요.',[]);renderGate();}
  if(view==='app')renderApp();else updateTravelHero();
}

/* ---------- ① 설정 ---------- */
$('#f-setup').addEventListener('submit', async e => {
  e.preventDefault(); const msg=$('#setup-msg'), btn=e.submitter;
  const name=$('#s-name').value.trim(), admin=$('#s-admin').value.trim();
  const others=$('#s-members').value.split(',').map(x=>x.trim()).filter(Boolean);
  const code=$('#s-code').value, adminCode=$('#s-admin-code').value;
  if (!name) return showMsg(msg,'여행 이름을 입력해 주세요.','bad');
  if (!guard([name,admin,...others],msg)) return;
  const names=[...new Set([admin,...others])];
  if(names.some(n=>!NAME_RE.test(n)))return showMsg(msg,'이름은 한글·영문 12자 이내로 입력해 주세요.','bad');
  if(names.length>7)return showMsg(msg,'관리자를 포함해 7명까지 등록할 수 있어요.','bad');
  if(code.length<6||code!==$('#s-code-again').value)return showMsg(msg,'가족 코드가 6자 이상이며 재입력과 같은지 확인해 주세요.','bad');
  if(adminCode.length<8||adminCode===code||adminCode!==$('#s-admin-again').value)return showMsg(msg,'관리자 코드는 가족 코드와 다르게 8자 이상으로 정하고, 똑같이 다시 입력해 주세요.','bad');
  const start=$('#s-start').value,end=$('#s-end').value;
  if(start&&end&&end<start)return showMsg(msg,'도착일이 출발일보다 빠릅니다.','bad');
  btn.disabled=true;
  try {
    const salt=token(12),adminSalt=token(12);
    state={schemaVersion:2,trip:{name,start,end,dest:'',members:names.map((n,i)=>({name:n,admin:i===0}))},salt,codeHash:await hash(code,salt),adminSalt,adminHash:await hash(adminCode,adminSalt),fails:0,lockUntil:0,excluded:[...BANNED,...PARTIAL],candidates:DEFAULT_CANDIDATES.map(([city,country])=>({city,country})),votes:{},links:DEFAULT_LINKS.map(l=>({...l})),schedule:[],packing:[],expenses:[],posts:[]};
    if(pendingImport){const credentials={salt:state.salt,codeHash:state.codeHash,adminSalt:state.adminSalt,adminHash:state.adminHash,fails:0,lockUntil:0};state={...pendingImport,...credentials,trip:{...pendingImport.trip,name}};}
    if(!save())return showMsg(msg,'저장하지 못했어요. 입력 내용을 확인한 뒤 다시 시도해 주세요.','bad');
    pendingImport=null;$('#f-setup').reset();me={...state.trip.members.find(m=>m.admin)};tab='overview';show('app');
  }catch(error){showMsg(msg,error.message,'bad');}finally{btn.disabled=false;}
});

/* ---------- ② 입장 ---------- */
let lockTimer = null;
function renderGate() {
  $("#g-title").textContent = state.trip.name + " 입장";
  const left = state.lockUntil - Date.now();
  const btn = $("#g-btn");
  clearInterval(lockTimer);
  if (left > 0) {
    btn.disabled = true;
    const tick = () => {
      const s = Math.max(0, Math.ceil((state.lockUntil - Date.now()) / 1000));
      showMsg($("#gate-msg"), `입장이 잠겼어요. ${Math.floor(s / 60)}분 ${s % 60}초 뒤에 다시 시도할 수 있어요.`, "bad");
      if (s <= 0) { clearInterval(lockTimer); state.fails = 0; save(); btn.disabled = false; showMsg($("#gate-msg"), ""); }
    };
    tick(); lockTimer = setInterval(tick, 1000);
  } else btn.disabled = false;
}
$('#f-gate').addEventListener('submit',async e=>{
  e.preventDefault();if(!state||state.lockUntil>Date.now())return;
  const btn=$('#g-btn');if(btn.disabled)return;btn.disabled=true;
  const name=$('#g-name').value.trim(),code=$('#g-code').value;
  const member=state.trip.members.find(m=>m.name===name),asAdmin=$('#g-as-admin').checked;
  try{
    let ok=!!member&&await verifyCode(code,state.salt,state.codeHash);
    if(ok&&asAdmin)ok=!!member.admin&&!!state.adminHash&&await verifyCode($('#g-admin-code').value,state.adminSalt,state.adminHash);
    if(ok){
      if(!commit(s=>{s.fails=0;s.lockUntil=0;}))return;
      me={...member,admin:asAdmin&&!!member.admin};$('#f-gate').reset();$('#g-admin-wrap').hidden=true;tab='overview';showMsg($('#gate-msg'),'');show('app');return;
    }
    if(!commit(s=>{if(s.lockUntil&&s.lockUntil<=Date.now()){s.fails=0;s.lockUntil=0;}s.fails=(s.fails||0)+1;if(s.fails>=5)s.lockUntil=Date.now()+300000;}))return;
    if(state.fails>=5)renderGate();else showMsg($('#gate-msg'),`이름 또는 코드가 맞지 않아요. 남은 기회 ${5-state.fails}회`,'bad');
  }catch(error){showMsg($('#gate-msg'),error.message,'bad');}finally{if(state.lockUntil<=Date.now())btn.disabled=false;}
});
$('#g-as-admin').onchange=e=>{$('#g-admin-wrap').hidden=!e.target.checked;};

/* ---------- ③ 앱 ---------- */
// [키, 이름, 아이콘 시트 번호(0~11: 여행지찾기·지도·가족·사진 / 후기·일정·달력·캐리어 / 비행기·여권·팁·하트)]
const TABS = [
  ["overview", "종합", 2], ["schedule", "일정표", 6], ["packing", "준비물", 7], ["money", "경비 정산", 5], ["recommend", "추천·투표", 11], ["roulette", "여행지 룰렛", 0],
  ["board", "사진·메모", 3], ["map", "세계 지도", 1], ["library", "자료실", 10], ["share", "설정·백업", 8]
];
const ico = (n, lg) => `<i class="ico${lg ? " lg" : ""}" style="--c:${n % 4};--r:${Math.floor(n / 4)}" aria-hidden="true"></i>`;
function renderApp() {
  cancelRoulette();
  const t = state.trip;
  const dates = (t.start || "날짜 미정") + (t.end ? " ~ " + t.end : "");
  const city = t.dest ? t.dest.split(" · ")[0] : "";
  setHero(city ? `<em>${esc(city)}</em>로 떠나는<br>${esc(t.name)}` : `우리 가족,<br>이번엔 <em>어디</em>로 떠날까요?`,
    city ? `${dates} · ${t.members.map(m => m.name).join(", ")}` : `${t.name} · 추천 여행지에 투표하고 룰렛으로 정해보세요.`,
    [["일정", dates], ["가족", t.members.length + "명"]]);
  $("#h-user").textContent = me.name + (me.admin ? " · 관리자" : "");
  const visible = TABS;
  if (!visible.find(([k]) => k === tab)) tab = "overview";
  const primary=visible.filter(([k])=>['overview','schedule','packing','money','recommend'].includes(k));
  const extra=visible.filter(([k])=>!primary.some(([p])=>p===k));
  const navButton=([k,l,n])=>`<button type="button" data-tab="${k}" aria-current="${k===tab?'page':'false'}" aria-selected="${k===tab}">${ico(n)}${l}</button>`;
  $('#tabs').innerHTML=primary.map(navButton).join('')+`<details class="more-nav"><summary>더보기</summary><div class="more-menu">${extra.map(navButton).join('')}</div></details>`;
  $('#panel').setAttribute('aria-label',visible.find(([k])=>k===tab)?.[1]||'여행 준비');
  $('#legacy-admin').hidden=!!state.adminHash||demoMode;

  ({ overview, schedule, packing, money, recommend, board, map, roulette, library, share })[tab]();
  updateTravelHero();
}

/* 투표 집계 */
function tally(key) {
  const v = state.votes[key] || {}, names = state.trip.members.map(m => m.name);
  const yes = names.filter(n => v[n] === "yes"), no = names.filter(n => v[n] === "no");
  return { yes, no, mine: v[me.name] || "", agreed: yes.length > names.length / 2, rejected: no.length >= names.length / 2 && no.length > 0 };
}
function voteButtons(key) {
  const t = tally(key);
  return `<span class="vote" style="display:inline-flex;gap:6px;flex:0 0 auto">
    <button class="${t.mine === "yes" ? "" : "ghost"}" data-vote="${esc(key)}" data-v="yes" style="padding:4px 10px;font-size:13px" aria-pressed="${t.mine === "yes"}">동의 ${t.yes.length}</button>
    <button class="${t.mine === "no" ? "danger" : "ghost"}" data-vote="${esc(key)}" data-v="no" style="padding:4px 10px;font-size:13px;${t.mine === "no" ? "background:var(--bad);color:var(--surface)" : ""}" aria-pressed="${t.mine === "no"}">거절 ${t.no.length}</button></span>`;
}
function bindVotes(rerender) {
  P().querySelectorAll("[data-vote]").forEach(b => b.onclick = () => {
    const k = b.dataset.vote, v = b.dataset.v;
    state.votes[k] ||= {};
    state.votes[k][me.name] = state.votes[k][me.name] === v ? undefined : v;
    save(); rerender();
  });
}
function safetyTag(country) {
  if (Core.isExcluded(country,state.excluded)) return `<span class="chip">룰렛 제외</span>`;
  if (CHECK_REGION.includes(country)) return `<span class="tag sun">일부 지역 경보 확인</span>`;
  return "";
}

/* 종합 */
function overviewOriginal() {
  const t = state.trip, s = settle();
  const today = localDate();
  const dd = t.start ? Math.round((new Date(t.start) - new Date(today)) / 864e5) : null;
  const ddText = dd === null ? "날짜 미정" : dd > 0 ? `D-${dd}` : dd === 0 ? "D-DAY" : (t.end && t.end >= today ? "여행 중" : "여행 끝");
  const nw = new Date(), nowKey = `${today} ${String(nw.getHours()).padStart(2, "0")}:${String(nw.getMinutes()).padStart(2, "0")}`;
  const sched = [...state.schedule].sort((a, b) => (a.date + a.time).localeCompare(b.date + b.time));
  const next = sched.find(i => (i.date + " " + i.time) >= nowKey);
  const done = state.packing.filter(p => p.done).length, total = state.packing.length;
  const allPlaces = [...state.candidates, ...RECS].filter((x, i, a) => a.findIndex(y => vkey(y.city, y.country) === vkey(x.city, x.country)) === i);
  const ranked = allPlaces.map(p => ({ p, t: tally(vkey(p.city, p.country)) })).filter(x => x.t.yes.length || x.t.no.length)
    .sort((a, b) => (b.t.yes.length - b.t.no.length) - (a.t.yes.length - a.t.no.length)).slice(0, 3);
  const myPack = state.packing.filter(p => p.owner === me.name && !p.done);
  const myMoves = s.moves.filter(m => m.from === me.name);
  const stat = (lbl, big, sub) => `<div class="card" style="gap:4px"><span class="muted small">${lbl}</span><span class="num" style="font-size:22px;font-family:var(--display)">${big}</span><span class="muted small">${sub}</span></div>`;
  P().innerHTML = `<div style="display:grid;gap:12px">
    <div class="grid2" style="grid-template-columns:repeat(auto-fit,minmax(160px,1fr))">
      ${stat("출발까지", ddText, esc(t.start || "출발일을 정해주세요"))}
      ${stat("목적지", esc(t.dest ? t.dest.split(" · ")[0] : "미정"), t.dest ? esc(t.dest.split(" · ")[1] || "") : "추천·투표에서 목적지 확정")}
      ${stat("총 경비", won(s.total), "내 부담액 " + won(s.owed[me.name]))}
      ${stat("준비물", `${done}/${total}`, total ? Math.round(done / total * 100) + "% 완료" : "항목 없음")}
    </div>
    <div class="features">
      <div class="feature">${ico(3, 1)}<div><h3>여행 사진 공유</h3><p class="small muted">사진으로 추억을 남기고 가족과 나눠요. 위치정보는 자동으로 지워져요.</p><button data-go="board">사진 올리기 ›</button></div></div>
      <div class="feature">${ico(5, 1)}<div><h3>일정 만들기</h3><p class="small muted">하루 단위 일정표를 만들고 가족과 함께 고쳐요.</p><button data-go="schedule">일정 만들기 ›</button></div></div>
      <div class="feature">${ico(10, 1)}<div><h3>가족 여행 팁</h3><p class="small muted">여행경보, 날씨, 공항 정보를 자료실에서 한눈에 봐요.</p><button data-go="library">자료 보기 ›</button></div></div>
    </div>
    <div class="card">
      <h2>${esc(me.name)}님이 챙길 것</h2>
      <ul class="list">
        ${next ? `<li><span class="tag">다음 일정</span><span class="grow">${esc(next.date)} ${esc(next.time)} · <b>${esc(next.place)}</b></span></li>` : ""}
        ${myPack.map(p => `<li><span class="tag">준비물</span><span class="grow">${esc(p.item)}</span></li>`).join("")}
        ${myMoves.map(m => `<li><span class="tag">정산</span><span class="grow">${esc(m.to)}님에게 보내기</span><span class="num">${won(m.amt)}</span></li>`).join("")}
        ${!next && !myPack.length && !myMoves.length ? `<li class="muted">할 일이 없어요.</li>` : ""}
      </ul>
    </div>
    <div class="card">
      <div class="row" style="align-items:center"><h2>가족 투표 현황</h2><button class="ghost" data-go="recommend" style="flex:0 0 auto">투표하러 가기</button></div>
      ${ranked.length ? `<ul class="list">${ranked.map(({ p, t: v }) => `<li><span class="grow"><b>${esc(p.city)}</b> <span class="muted small">${esc(p.country)}</span></span>
        ${v.agreed ? `<span class="chip ok">가족 합의</span>` : ""}<span class="small num">동의 ${v.yes.length} · 거절 ${v.no.length}</span></li>`).join("")}</ul>`
        : `<p class="muted">아직 투표가 없어요. 추천 여행지에서 동의·거절을 눌러보세요.</p>`}
    </div>
    <div class="card">
      <h2>경비 요약</h2>
      <div class="tblwrap"><table><thead><tr><th>이름</th><th class="r">낸 돈</th><th class="r">정산 후</th></tr></thead><tbody>
        ${t.members.map(m => { const diff = s.paid[m.name] - s.owed[m.name]; return `<tr><td>${esc(m.name)}</td><td class="r num">${won(s.paid[m.name])}</td>
          <td class="r num" style="color:${diff >= 0 ? "var(--good)" : "var(--bad)"}">${diff >= 0 ? "받을 돈 " : "보낼 돈 "}${won(Math.abs(diff))}</td></tr>`; }).join("")}
      </tbody></table></div>
    </div>
    <div class="grid2">
      ${stat("일정", state.schedule.length + "개", [...new Set(state.schedule.map(i => i.date))].length + "일치")}
      ${stat("게시글", state.posts.length + "개", "사진 " + state.posts.filter(p => p.img).length + "장")}
      ${stat("자료", state.links.length + "개", "자료실 링크")}
    </div>
  </div>`;
  P().querySelectorAll("[data-go]").forEach(b => b.onclick = () => { tab = b.dataset.go; renderApp(); });
}

/* 추천 여행지 + 동의/거절 */
let recFilter = "all";
function recommendOriginal() {
  const regions = [...new Set(RECS.map(r => r.region))];
  const list = RECS.filter(r => recFilter === "all" || r.src === recFilter || r.region === recFilter);
  const inCand = r => state.candidates.some(c => vkey(c.city, c.country) === vkey(r.city, r.country));
  const photoC = state.candidates.filter(c => PHOTOS[vkey(c.city, c.country)]);
  P().innerHTML = `<div class="card">
    <div><h2><span class="sunmark"></span>인기 가족여행</h2><p class="muted small">우리 가족 후보지예요. 구성원 과반이 동의하면 ‘가족 합의’가 되고, 룰렛에서 합의한 곳만 돌릴 수 있어요.</p></div>
    ${photoC.length ? `<div class="dests">${photoC.map(c => { const k = vkey(c.city, c.country), v = tally(k), ph = PHOTOS[k]; return `<article class="dest">
      <div class="ph" style="background-image:url('${DEST_IMG[ph.img]}')" role="img" aria-label="${esc(c.city)} 풍경"><span class="badge ${c.country === "대한민국" ? "" : "abroad"}">${c.country === "대한민국" ? "국내" : "해외"}</span></div>
      <div class="body"><b>${esc(ph.title)}</b><span class="muted small">📍 ${esc(c.country === "대한민국" ? c.city : c.country + " " + c.city)}</span><span class="small">${esc(ph.desc)}</span>
      ${v.agreed ? `<span class="chip ok" style="justify-self:start">가족 합의</span>` : ""}<div>${voteButtons(k)}</div></div></article>`; }).join("")}</div>` : ""}
    <ul class="list">${state.candidates.filter(c => !PHOTOS[vkey(c.city, c.country)]).map(c => { const k = vkey(c.city, c.country), v = tally(k); return `<li style="flex-wrap:wrap">
      <span class="grow"><b>${esc(c.city)}</b> <span class="muted small">${esc(c.country)}</span> ${safetyTag(c.country)} ${v.agreed ? `<span class="chip ok">가족 합의</span>` : ""}
      ${v.yes.length || v.no.length ? `<br><span class="muted small">동의: ${esc(v.yes.join(", ") || "-")} · 거절: ${esc(v.no.join(", ") || "-")}</span>` : ""}</span>
      ${Core.isExcluded(c.country,state.excluded) ? `<span class="muted small">투표 불가</span>` : voteButtons(k)}</li>`; }).join("")}</ul>
  </div>
  <div class="card">
    <div><h2>2026 세계 추천 여행지</h2><p class="muted small">기준일 <span class="num">${RECS_DATE}</span> · 출처: <a href="${SRC.LP.url}" target="_blank" rel="noopener noreferrer">${SRC.LP.name}</a>, <a href="${SRC.NYT.url}" target="_blank" rel="noopener noreferrer">${SRC.NYT.name}</a></p></div>
    <div class="chiptabs" id="rec-filter">
      ${[["all", "전체"], ["LP", "론리플래닛"], ["NYT", "뉴욕타임스"], ...regions.map(r => [r, r])].map(([k, l]) => `<button data-f="${esc(k)}" aria-selected="${recFilter === k}">${esc(l)}</button>`).join("")}
    </div>
    <ul class="list">${list.map(r => { const k = vkey(r.city, r.country), banned = Core.isExcluded(r.country,state.excluded); return `<li style="flex-wrap:wrap">
      <span class="tag" style="flex:0 0 auto">${r.src === "LP" ? "론리" : "NYT"} ${r.rank}</span>
      <span class="grow"><b>${esc(r.city)}</b> <span class="muted small">${esc(r.country)} · ${esc(r.region)}</span> ${safetyTag(r.country)}<br><span class="muted small">${esc(r.why)}</span></span>
      ${banned ? "" : voteButtons(k)}
      ${banned ? "" : inCand(r) ? `<span class="chip ok">후보 등록됨</span>` : `<button class="ghost" data-add="${esc(k)}" style="padding:4px 10px;font-size:13px">후보에 추가</button>`}</li>`; }).join("")}</ul>
    <p class="pii-hint">‘일부 지역 경보 확인’ 표시는 나라 전체가 금지는 아니지만 국경·일부 지역에 경보가 있을 수 있는 곳이에요. 출발 전 해외안전여행에서 지역별 단계를 확인하세요.</p>
  </div>`;
  P().querySelectorAll("[data-f]").forEach(b => b.onclick = () => { recFilter = b.dataset.f; recommend(); });
  P().querySelectorAll("[data-add]").forEach(b => b.onclick = () => {
    const [city, country] = b.dataset.add.split("|"); state.candidates.push({ city, country }); save(); recommend();
  });
  bindVotes(recommend);
}

/* 자료실 */
function library() {
  P().innerHTML = `<div class="card">
    <h2>자료실</h2>
    <p class="muted small">여행에 도움이 되는 사이트를 모아두는 곳이에요. 비상시 외교부 영사콜센터: <span class="num">+82-2-3210-0404</span> (24시간)</p>
    <ul class="list">${state.links.map(l => `<li><span class="grow"><a href="${esc(l.url)}" target="_blank" rel="noopener noreferrer">${esc(l.title)}</a><br><span class="muted small">${esc(l.by === "기본" ? "기본 자료" : l.by + "님이 추가")}</span></span>
      ${l.by !== "기본" && (l.by === me.name || me.admin) ? `<button class="icon" data-del="${l.id}" aria-label="삭제">✕</button>` : ""}</li>`).join("")}</ul>
    <form id="f-lk" class="row" novalidate>
      <label>제목<input id="lk-title" maxlength="40" placeholder="예: 우도 배편 시간표"></label>
      <label>주소 (https://로 시작)<input id="lk-url" maxlength="300" placeholder="https://"></label>
      <button type="submit">추가</button>
    </form>${PII_HINT}<div id="lk-msg"></div>
  </div>`;
  $("#f-lk").addEventListener("submit", e => {
    e.preventDefault();
    const title = $("#lk-title").value.trim(), url = $("#lk-url").value.trim();
    let parsed,decoded;
    try{parsed=new URL(url);decoded=decodeURIComponent(url);}catch{return showMsg($('#lk-msg'),'올바른 https 주소를 입력해 주세요.','bad');}
    if(!title||parsed.protocol!=='https:'||parsed.username||parsed.password)return showMsg($('#lk-msg'),'인증정보가 없는 https 주소와 제목을 입력해 주세요.','bad');
    if(!guard([title,decoded],$('#lk-msg')))return;
    if(commit(s=>s.links.push({id:uid(),title,url:parsed.href,by:me.name})))library();
  });
  P().querySelectorAll("[data-del]").forEach(b => b.onclick = () => { removeRecord("links",b.dataset.del,library); });
}
$("#tabs").addEventListener("click", e => { const b = e.target.closest("[data-tab]"); if (b) { tab = b.dataset.tab; renderApp(); } });
$("#logout").addEventListener("click", () => { homeEntry(); });
let resetArmed=false;
$('#reset').onclick=()=>{if(!me?.admin||demoMode)return;if(!resetArmed){resetArmed=true;$('#reset').textContent='일정·사진·경비도 삭제됩니다. 다시 눌러 삭제';setTimeout(()=>{resetArmed=false;$('#reset').textContent='현재 여행 삭제';},5000);return;}try{localStorage.removeItem(activeKey);}catch{alert('삭제하지 못했어요. 브라우저 설정을 확인해 주세요.');return;}resetArmed=false;$('#reset').textContent='현재 여행 삭제';homeEntry();};

const P = () => $("#panel");
const memberOptions = (sel) => state.trip.members.map(m => `<option ${m.name === sel ? "selected" : ""}>${esc(m.name)}</option>`).join("");
const PII_HINT = `<p class="pii-hint">개인정보는 입력하지 마세요. 주민번호·생년월일·전화번호·주소·계좌번호 등의 의심 표현은 저장을 차단합니다.</p>`;

/* 일정표 */
function schedule(editId = null) {
  const editing = typeof editId === "string" ? state.schedule.find(x => x.id === editId) : null;
  const items = [...state.schedule].sort((a, b) => (a.date + a.time).localeCompare(b.date + b.time));
  const days = [...new Set(items.map(x => x.date))];
  const { start, end } = state.trip;
  const dayNo = d => start ? Math.round((new Date(d + "T00:00:00") - new Date(start + "T00:00:00")) / 864e5) + 1 : null;
  P().innerHTML = `<div class="card">
    <div class="section-head"><h2>날짜별 일정표</h2><p class="small muted">${start ? esc(start) : "출발일 미정"}${end ? " ~ " + esc(end) : ""}</p></div>
    <form id="f-sch" class="row" novalidate>
      <label>날짜<input id="sc-date" type="date" required ${start ? `min="${esc(start)}"` : ""} ${end ? `max="${esc(end)}"` : ""} value="${esc(editing?.date || start || "")}"></label>
      <label style="flex:0 1 110px">시간<input id="sc-time" type="time" required value="${esc(editing?.time || "10:00")}"></label>
      <label>장소·할 일<input id="sc-place" maxlength="40" required value="${esc(editing?.place || "")}" placeholder="예: 한라산 영실코스"></label>
      <label>메모<input id="sc-note" maxlength="60" value="${esc(editing?.note || "")}" placeholder="선택"></label>
      <button type="submit">${editing ? "수정 저장" : "일정 추가"}</button>
      ${editing ? '<button type="button" class="ghost" id="sc-cancel">수정 취소</button>' : ""}
    </form>
    ${PII_HINT}<div id="sc-msg" role="status" aria-live="polite"></div>
    ${days.length ? days.map(d => `<div><h3 class="day">${dayNo(d) ? dayNo(d) + "일차 · " : ""}${esc(d)}</h3><ul class="list">${items.filter(x => x.date === d).map(x => `
      <li><span class="time">${esc(x.time)}</span><span class="grow"><b>${esc(x.place)}</b>${x.note ? `<br><span class="muted small">${esc(x.note)}</span>` : ""}</span>
      <button class="icon" data-edit="${esc(x.id)}" aria-label="${esc(x.place)} 수정">수정</button><button class="icon" data-del="${esc(x.id)}" aria-label="${esc(x.place)} 삭제">삭제</button></li>`).join("")}</ul></div>`).join("")
      : '<p class="empty-state">아직 일정이 없어요. 첫 일정을 추가해 보세요.</p>'}
  </div>`;
  $("#f-sch").addEventListener("submit", e => {
    e.preventDefault();
    const msg = $("#sc-msg"), place = $("#sc-place").value.trim(), note = $("#sc-note").value.trim(), date = $("#sc-date").value, time = $("#sc-time").value;
    if (!date || !time || !place) return showMsg(msg, "날짜, 시간, 장소를 입력해 주세요.", "bad");
    if ((start && date < start) || (end && date > end)) return showMsg(msg, "여행 기간 안의 날짜를 선택해 주세요. 기간은 설정에서 변경할 수 있어요.", "bad");
    if (!$("#f-sch").checkValidity()) return $("#f-sch").reportValidity();
    if (!guard([place, note], msg)) return;
    const record = { id: editing?.id || uid(), date, time, place, note };
    if (!commit(s => { if (editing) s.schedule[s.schedule.findIndex(x => x.id === editing.id)] = record; else s.schedule.push(record); })) return showMsg(msg, "저장하지 못했어요. 입력 내용은 그대로 두었으니 다시 시도해 주세요.", "bad");
    schedule();
  });
  if ($("#sc-cancel")) $("#sc-cancel").onclick = () => schedule();
  P().querySelectorAll("[data-edit]").forEach(b => b.onclick = () => { schedule(b.dataset.edit); $("#sc-place").focus(); });
  P().querySelectorAll("[data-del]").forEach(b => b.onclick = () => removeRecord("schedule", b.dataset.del, () => schedule()));
}

function packing(editId = null) {
  const editing = typeof editId === "string" ? state.packing.find(x => x.id === editId) : null;
  const done = state.packing.filter(x => x.done).length, total = state.packing.length;
  P().innerHTML = `<div class="card">
    <div class="section-head"><h2>준비물 체크리스트</h2><span id="pk-progress" class="muted small">${done}/${total} 완료</span></div>
    <div class="bar" role="progressbar" aria-label="준비물 완료" aria-valuemin="0" aria-valuemax="${total || 1}" aria-valuenow="${done}"><i id="pk-progress-bar" style="width:${total ? done / total * 100 : 0}%"></i></div>
    <form id="f-pk" class="row" novalidate>
      <label>준비물<input id="pk-item" maxlength="30" required value="${esc(editing?.item || "")}" placeholder="예: 선크림"></label>
      <label style="flex:0 1 140px">담당<select id="pk-owner">${memberOptions(editing?.owner || me.name)}</select></label>
      <button type="submit">${editing ? "수정 저장" : "준비물 추가"}</button>
      ${editing ? '<button type="button" class="ghost" id="pk-cancel">수정 취소</button>' : ""}
    </form>${PII_HINT}<div id="pk-msg" role="status" aria-live="polite"></div>
    <ul class="list">${state.trip.members.map(m => state.packing.filter(x => x.owner === m.name).map(x => `
      <li><input type="checkbox" id="pk-${esc(x.id)}" data-chk="${esc(x.id)}" ${x.done ? "checked" : ""} style="width:20px;height:20px;flex:0 0 auto">
      <label for="pk-${esc(x.id)}" data-packing-label="${esc(x.id)}" class="grow" style="display:block;font-size:15px;color:${x.done ? "var(--muted)" : "var(--ink)"};font-weight:400;text-decoration:${x.done ? "line-through" : "none"}">${esc(x.item)}</label>
      <span class="tag">${esc(x.owner)}</span><button class="icon" data-edit="${esc(x.id)}" aria-label="${esc(x.item)} 수정">수정</button><button class="icon" data-del="${esc(x.id)}" aria-label="${esc(x.item)} 삭제">삭제</button></li>`).join("")).join("") || '<li class="muted">아직 준비물이 없어요.</li>'}</ul>
  </div>`;
  $("#f-pk").addEventListener("submit", e => {
    e.preventDefault();
    const msg = $("#pk-msg"), item = $("#pk-item").value.trim(), owner = $("#pk-owner").value;
    if (!item) return showMsg(msg, "준비물을 입력해 주세요.", "bad");
    if (!state.trip.members.some(m => m.name === owner)) return showMsg(msg, "담당자를 다시 선택해 주세요.", "bad");
    if (!$("#f-pk").checkValidity()) return $("#f-pk").reportValidity();
    if (!guard([item], msg)) return;
    const record = { id: editing?.id || uid(), item, owner, done: editing?.done || false };
    if (!commit(s => { if (editing) s.packing[s.packing.findIndex(x => x.id === editing.id)] = record; else s.packing.push(record); })) return showMsg(msg, "저장하지 못했어요. 입력 내용은 그대로 두었으니 다시 시도해 주세요.", "bad");
    packing();
  });
  if ($("#pk-cancel")) $("#pk-cancel").onclick = () => packing();
  P().querySelectorAll("[data-edit]").forEach(b => b.onclick = () => { packing(b.dataset.edit); $("#pk-item").focus(); });
  P().querySelectorAll("[data-chk]").forEach(c => c.onchange = () => {
    const checked = c.checked;
    if (!commit(s => { const record = s.packing.find(x => x.id === c.dataset.chk); if (record) record.done = checked; })) { c.checked = !checked; return showMsg($("#pk-msg"), "완료 상태를 저장하지 못했어요. 다시 시도해 주세요.", "bad"); }
    const label = [...P().querySelectorAll("[data-packing-label]")].find(x => x.dataset.packingLabel === c.dataset.chk);
    if (label) { label.style.textDecoration = checked ? "line-through" : "none"; label.style.color = checked ? "var(--muted)" : "var(--ink)"; }
    const n = state.packing.filter(x => x.done).length;
    $("#pk-progress").textContent = `${n}/${state.packing.length} 완료`;
    $("#pk-progress-bar").style.width = `${state.packing.length ? n / state.packing.length * 100 : 0}%`;
    $("#pk-progress-bar").parentElement.setAttribute("aria-valuenow", String(n));
    showMsg($("#pk-msg"), "");
  });
  P().querySelectorAll("[data-del]").forEach(b => b.onclick = () => removeRecord("packing", b.dataset.del, () => packing()));
}

function settle() { return Core.settle(state); }

function money(editId = null) {
  const editing = typeof editId === "string" ? state.expenses.find(x => x.id === editId) : null;
  const summary = settle(), selected = editing?.participants || state.trip.members.map(m => m.name);
  P().innerHTML = `<div class="card">
    <div class="section-head"><h2>경비 정산</h2><span class="tag sun">총 지출 ${won(summary.total)}</span></div>
    <p class="small muted">지출마다 함께 부담할 사람을 선택하세요. 참여자는 기록에 저장되며 새 구성원을 추가해도 과거 지출에는 자동으로 포함되지 않아요.</p>
    <form id="f-ex" style="display:grid;gap:14px" novalidate>
      <div class="row">
        <label>항목<input id="ex-item" maxlength="30" required value="${esc(editing?.item || "")}" placeholder="예: 저녁 식사"></label>
        <label style="flex:0 1 160px">금액(원)<input id="ex-amt" type="number" min="1" max="100000000" step="1" required inputmode="numeric" value="${editing ? esc(editing.amount) : ""}"></label>
        <label style="flex:0 1 140px">낸 사람<select id="ex-payer">${memberOptions(editing?.payer || me.name)}</select></label>
      </div>
      <fieldset class="expense-participants" style="border:1px solid var(--line);border-radius:12px;padding:12px"><legend class="small">함께 부담할 사람</legend><div class="chips">${state.trip.members.map((m, i) => `<label for="ex-person-${i}" style="display:flex;align-items:center;gap:7px;padding:6px 10px;color:var(--ink)"><input type="checkbox" id="ex-person-${i}" data-ex-person value="${esc(m.name)}" ${selected.includes(m.name) ? "checked" : ""} style="width:18px;height:18px">${esc(m.name)}</label>`).join("")}</div></fieldset>
      <div class="row" style="justify-content:start"><button type="submit">${editing ? "수정 저장" : "지출 기록"}</button>${editing ? '<button type="button" class="ghost" id="ex-cancel">수정 취소</button>' : ""}</div>
    </form>${PII_HINT}<div id="ex-msg" role="status" aria-live="polite"></div>
    <div class="tblwrap"><table><caption class="small muted" style="text-align:left;padding-bottom:8px">지출 내역 · 수정하면 해당 항목의 부담액도 다시 계산해요.</caption><thead><tr><th scope="col">항목</th><th scope="col">낸 사람 / 참여자</th><th scope="col" class="r">금액</th><th scope="col">관리</th></tr></thead><tbody>
      ${state.expenses.map(x => `<tr><td>${esc(x.item)}</td><td>${esc(x.payer)}<br><span class="small muted">참여: ${esc((x.participants || []).join(", "))}</span></td><td class="r num">${won(x.amount)}</td><td><div style="display:flex;gap:4px"><button class="icon" data-edit="${esc(x.id)}" aria-label="${esc(x.item)} 수정">수정</button><button class="icon" data-del="${esc(x.id)}" aria-label="${esc(x.item)} 삭제">삭제</button></div></td></tr>`).join("") || '<tr><td colspan="4" class="muted">아직 기록이 없어요.</td></tr>'}
      <tr><th scope="row" colspan="2">합계</th><td class="r num"><b>${won(summary.total)}</b></td><td></td></tr>
    </tbody></table></div>
    <h3>사람별 부담액</h3>
    <p class="small muted">각 항목을 참여자끼리 나눠요. 나누어떨어지지 않는 금액은 기록에 저장된 참여자 순서대로 1원씩 배분해 합계를 맞춥니다.</p>
    <div class="tblwrap"><table><thead><tr><th scope="col">구성원</th><th scope="col" class="r">낸 금액</th><th scope="col" class="r">부담액</th><th scope="col" class="r">차액</th></tr></thead><tbody>${state.trip.members.map(m => { const paid = summary.paid[m.name] || 0, owed = summary.owed[m.name] || 0, balance = paid - owed; return `<tr><th scope="row">${esc(m.name)}</th><td class="r num">${won(paid)}</td><td class="r num">${won(owed)}</td><td class="r num">${balance > 0 ? "+" : ""}${won(balance)}</td></tr>`; }).join("")}</tbody></table></div>
    <h3>누가 누구에게 보내면 될까요</h3>
    ${summary.moves.length ? `<ul class="list">${summary.moves.map(x => `<li><span class="grow"><b>${esc(x.from)}</b> → <b>${esc(x.to)}</b></span><span class="num">${won(x.amt)}</span></li>`).join("")}</ul>` : '<p class="muted">정산할 금액이 없어요.</p>'}
    <p class="pii-hint">송금에 필요한 계좌번호는 기록하지 마세요.</p>
  </div>`;
  $("#f-ex").addEventListener("submit", e => {
    e.preventDefault();
    const msg = $("#ex-msg"), item = $("#ex-item").value.trim(), amount = Number($("#ex-amt").value), payer = $("#ex-payer").value;
    const participants = [...P().querySelectorAll("[data-ex-person]:checked")].map(x => x.value);
    if (!item || !Number.isSafeInteger(amount) || amount < 1 || amount > 100000000) return showMsg(msg, "항목과 1원 이상 1억 원 이하의 정수 금액을 입력해 주세요.", "bad");
    if (!participants.length) return showMsg(msg, "함께 부담할 사람을 한 명 이상 선택해 주세요.", "bad");
    const names = state.trip.members.map(m => m.name);
    if (!names.includes(payer) || participants.some(n => !names.includes(n))) return showMsg(msg, "구성원 정보를 다시 확인해 주세요.", "bad");
    if (!$("#f-ex").checkValidity()) return $("#f-ex").reportValidity();
    if (!guard([item], msg)) return;
    const record = { id: editing?.id || uid(), item, amount, payer, participants };
    if (!commit(s => { if (editing) s.expenses[s.expenses.findIndex(x => x.id === editing.id)] = record; else s.expenses.push(record); })) return showMsg(msg, "저장하지 못했어요. 입력 내용은 그대로 두었으니 다시 시도해 주세요.", "bad");
    money();
  });
  if ($("#ex-cancel")) $("#ex-cancel").onclick = () => money();
  P().querySelectorAll("[data-edit]").forEach(b => b.onclick = () => { money(b.dataset.edit); $("#ex-item").focus(); });
  P().querySelectorAll("[data-del]").forEach(b => b.onclick = () => removeRecord("expenses", b.dataset.del, () => money()));
}

function stripAndShrink(file) {
  return new Promise((res,rej)=>{
    if(!['image/jpeg','image/png','image/webp','image/gif'].includes(file.type)){rej(new Error('JPG·PNG·WebP·GIF 사진을 선택해 주세요.'));return;}
    const url=URL.createObjectURL(file),img=new Image();
    const clean=()=>URL.revokeObjectURL(url);
    img.onload=()=>{
      try{
        if(!img.naturalWidth||!img.naturalHeight||img.naturalWidth*img.naturalHeight>40000000)throw new Error('사진 크기가 너무 커요. 4천만 화소 이하의 사진을 선택해 주세요.');
        const max=900,k=Math.min(1,max/Math.max(img.naturalWidth,img.naturalHeight)),c=document.createElement('canvas');
        c.width=Math.max(1,Math.round(img.naturalWidth*k));c.height=Math.max(1,Math.round(img.naturalHeight*k));
        const g=c.getContext('2d');if(!g)throw new Error('사진을 처리하지 못했어요.');
        g.drawImage(img,0,0,c.width,c.height);res(c.toDataURL('image/jpeg',0.75));
      }catch(error){rej(error);}finally{clean();}
    };
    img.onerror=()=>{clean();rej(new Error('사진을 읽지 못했어요. 다른 사진을 골라 주세요.'));};img.src=url;
  });
}

function board() {
  const posts = [...state.posts].sort((a, b) => b.time - a.time);
  P().innerHTML = `<div class="card">
    <h2>사진·메모 게시판</h2>
    <form id="f-bd" style="display:grid;gap:10px" novalidate>
      <label>글<textarea id="bd-text" maxlength="300" placeholder="오늘 여행 어땠나요?"></textarea></label>
      <label>사진 (선택 · 위치정보는 자동으로 지워져요)<input id="bd-img" type="file" accept="image/jpeg,image/png,image/webp,image/gif"></label>
      ${PII_HINT}<div id="bd-msg"></div>
      <div><button type="submit">올리기</button></div>
    </form>
    <div>${posts.map(p => `<article class="post">
      <div class="row" style="align-items:center"><b style="flex:0 0 auto">${esc(p.author)}</b><span class="muted small">${new Date(p.time).toLocaleString("ko-KR", { month: "short", day: "numeric", hour: "2-digit", minute: "2-digit" })}</span>
      ${p.author === me.name || me.admin ? `<button class="icon" data-del="${p.id}" aria-label="삭제" style="flex:0 0 auto">✕</button>` : ""}</div>
      ${p.text ? `<p style="overflow-wrap:anywhere">${esc(p.text)}</p>` : ""}${p.img ? `<img src="${p.img}" alt="${esc(p.author)}님이 올린 여행 사진">` : ""}
    </article>`).join("") || `<p class="muted">첫 글을 남겨보세요.</p>`}</div>
  </div>`;
  $("#f-bd").addEventListener("submit", async e => {
    e.preventDefault();
    const text = $("#bd-text").value.trim(), file = $("#bd-img").files[0];
    if (!text && !file) return showMsg($("#bd-msg"), "글이나 사진 중 하나는 있어야 해요.", "bad");
    if (!guard([text], $("#bd-msg"))) return;
    const postingKey=activeKey,author=me.name,btn=e.submitter;
    if(btn.disabled)return;btn.disabled=true;
    let img='';
    try{
      if(file){if(file.size>20*1024*1024)throw new Error('사진은 20MB 이하로 선택해 주세요.');img=await stripAndShrink(file);}
      if(activeKey!==postingKey||!me||tab!=='board'||!e.target.isConnected)return;
      if(!commit(s=>s.posts.push({id:uid(),author,text,img,time:Date.now()})))return;
    }catch(error){return showMsg($('#bd-msg'),error.message||'사진을 읽지 못했어요. 다른 사진을 골라 주세요.','bad');}
    finally{if(btn.isConnected)btn.disabled=false;}
    board();
  });
  P().querySelectorAll("[data-del]").forEach(b => b.onclick = () => { removeRecord("posts",b.dataset.del,board); });
}

